module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output reg wfull,
    output reg rempty,
    output reg [WIDTH-1:0]	rdata
);

    reg [ADDR_WIDTH-1:0] wp;
    reg [ADDR_WIDTH-1:0] rp;
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram_inst (
        .wclk(wclk),
        .wenc(winc),
        .waddr(wp),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc),
        .raddr(rp),
        .rdata(rdata)
    );

    reg [ADDR_WIDTH-1:0] wp_syn;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wp_syn <= 0;
        end else begin
            wp_syn <= wp;
        end
    end

    reg [ADDR_WIDTH-1:0] rp_syn;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rp_syn <= 0;
        end else begin
            rp_syn <= rp;
        end
    end

    assign wfull = (wp_syn == {~rp_syn[ADDR_WIDTH:ADDR_WIDTH-1], rp_syn[ADDR_WIDTH-2:0]});
    assign rempty = (rp_syn == wp_syn);

endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
